/**
 * The goldens of the share pictures (#138): for every picture and case in `share-golden.test.cases.ts` the SVG string must be byte-identical to
 * `__golden__/<picture>/<case>.svg`. They were captured once, on the code before the shared builder existed, and are NEVER regenerated by
 * a change to a builder or a content module. Only the SVG is compared: the PNG is made in the browser, which is not byte-stable across machines.
 *
 * Capture (first checkpoint only): `GOLDEN_CAPTURE=1 npx vitest run src/lib/share-golden.test.ts` writes the files that do not exist yet and
 * refuses to overwrite one (flag `wx`), so a golden cannot be changed by accident.
 *
 * An INTENDED layout change of one picture (only with an owner decision as its reason) is recaptured on purpose: delete that picture's folder under
 * `__golden__/`, run the capture command above, review the new files and commit them in the change that alters the builder, naming the decision.
 * The other pictures' goldens must stay byte-identical. Done once so far: the Brasil picture, 1080x1710 to the fixed 1080x1350 share format
 * (private#106, D-038).
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { GOLDEN_CASES, MIN_CASES } from './share-golden.test.cases'

const DIR = resolve(__dirname, '__golden__')
const file = (picture: string, name: string) => resolve(DIR, picture, `${name}.svg`)
const capturing = Boolean(process.env.GOLDEN_CAPTURE)

describe('the golden set', () => {
  it.each(Object.entries(MIN_CASES))('%s keeps at least %i cases', (picture, min) => {
    expect(Object.keys(GOLDEN_CASES[picture] ?? {}).length).toBeGreaterThanOrEqual(min)
  })

  it.skipIf(capturing)('has a file for every case and no file without a case', () => {
    for (const [picture, cases] of Object.entries(GOLDEN_CASES)) {
      expect(readdirSync(resolve(DIR, picture)).sort(), picture).toEqual(Object.keys(cases).map((n) => `${n}.svg`).sort())
    }
  })
})

for (const [picture, cases] of Object.entries(GOLDEN_CASES))
  describe(`golden: ${picture}`, () => {
    it.each(Object.keys(cases))('%s is byte-identical to its golden', (name) => {
      const svg = cases[name]!()
      if (capturing) {
        if (!existsSync(file(picture, name))) {
          mkdirSync(dirname(file(picture, name)), { recursive: true })
          writeFileSync(file(picture, name), svg, { encoding: 'utf-8', flag: 'wx' })
        }
        return
      }
      expect(svg === readFileSync(file(picture, name), 'utf-8')).toBe(true)
    })
  })
